from itertools import permutations

tasks = {
    'T1': 2,
    'T2': 3,
    'T3': 1,
    'T4': 2
}

# Precedences: T1 -> T3, T2 -> T3, T2 -> T4
precedences = {
    'T3': ['T1', 'T2'],
    'T4': ['T2']
}

def solve():
    # Since it's a small set, we can simulate the scheduling.
    # We want to find the minimum makespan for 2 workers.

    best_makespan = float('inf')

    # Try all possible valid sequences of task assignments
    # A sequence is valid if predecessors are finished before a task starts.

    def get_makespan(sequence):
        worker_free_time = [0, 0]
        finish_times = {}

        for task in sequence:
            duration = tasks[task]
            # Find earliest start time based on predecessors
            earliest_start = 0
            for pred in precedences.get(task, []):
                earliest_start = max(earliest_start, finish_times[pred])

            # Worker must also be free
            # We assign to the worker who becomes free earliest
            worker_free_time.sort()
            start_time = max(earliest_start, worker_free_time[0])
            finish_times[task] = start_time + duration
            worker_free_time[0] = start_time + duration

        return max(worker_free_time)

    # Generate all permutations and filter by precedence
    import itertools
    for p in itertools.permutations(['T1', 'T2', 'T3', 'T4']):
        valid = True
        for i, task in enumerate(p):
            preds = precedences.get(task, [])
            for pred in preds:
                if pred not in p[:i]:
                    valid = False
                    break
            if not valid: break

        if valid:
            best_makespan = min(best_makespan, get_makespan(p))

    return best_makespan

print(solve())

